import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"预取时机与污染","description":"","frontmatter":{"title":"预取时机与污染","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/prefetch-timing-pollution.md","filePath":"cs/prefetch-timing-pollution.md","lastUpdated":1789023840000}'),h={name:"cs/prefetch-timing-pollution.md"};function m(A,a,_,E,f,P){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="预取时机与污染" tabindex="-1">预取时机与污染 <a class="header-anchor" href="#预取时机与污染" aria-label="Permalink to &quot;预取时机与污染&quot;">​</a></h1><div class="epigraph"><p>太早：块被踢走，预取白做；太晚：需求 load 仍付缺失；猜错：热行被挤掉，DRAM 带宽还给别人用。</p><footer>—— 据 Srinath et al., Feedback Directed Prefetching, MICRO 2007；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/stride-stream-prefetch">上一课</a> 会发 \\(addr+k\\Delta\\)。\\(k\\) 太大或流已经结束，就变成污染。<a href="/cs/rrip-dead-block">RRIP</a> 给了插入位置，但没有说预取器何时该节流。本课不重检步长。缺口是<strong>及时性与污染的度量，以及用反馈关掉或拉开预取。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>覆盖率：需求 miss 里有多少本可被预取覆盖。准确率：发出的预取里有多少被真正用到。污染：因预取插入而导致的额外需求 miss。带宽：预取占用 DRAM 后，需求 miss 排队变长。四者打架。缺口不是再加一种 \\(\\Delta\\) 检测，而是<strong>运行时看这四者，调 \\(k\\) 或关掉该流。</strong></p><p><span class="marginnote">Feedback Directed Prefetching（FDP）用预取队列里「被需求命中 / 被替换前未用」等计数调节攻击性。许多 LLC 预取器带类似节流。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每条预取带使用位：被需求 load 命中则记成功；被替换时仍未用则记浪费。污染：给被预取踢掉的行记「若还在则会命中」的近似（如 victim 里短期命中）。反馈：准确率低则增大插入 RRPV（更容易被踢）或减小 \\(k\\)；污染高则抑制该 PC 的预取。</p>',8)),(e(),n(p,null,{default:r(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PF%5B%22%E5%8F%91%E5%87%BA%E9%A2%84%E5%8F%96%22%5D%20--%3E%20USE%5B%22%E9%9C%80%E6%B1%82%E6%98%AF%E5%90%A6%E7%94%A8%E5%88%B0%22%5D%0A%20%20PF%20--%3E%20POLL%5B%22%E6%98%AF%E5%90%A6%E6%8C%A4%E6%8E%89%E7%83%AD%E8%A1%8C%22%5D%0A%20%20USE%20--%3E%20FB%5B%22%E8%B0%83%E8%B7%9D%E7%A6%BB%20%2F%20%E5%BC%80%E5%85%B3%22%5D%0A%20%20POLL%20--%3E%20FB%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>软件预取同样可污染；编译器插入密度过高时，硬件反馈仍适用，或 OS 关硬件预取。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><a href="/cs/mlp-memory-parallelism">MLP</a> 的 MSHR 是共享资源：错预取不仅污染 SRAM，还堵住真缺失的登记。及时性与 DRAM 调度互动：同一 bank 上提前太多会造成行缓冲颠簸。这些不改 ISA，只改 CPI 的访存项。</p><p>与一致性：预取读可能把行变成 S，干扰他核的 M——多核下预取攻击性更要收敛。分区课会再把带宽和命中分到 QoS 里。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入指针追逐的依赖预取器细节。也不把「预取指令作为侧信道」写成攻击教程；机制上预取会改 cache 状态，安全课会用到，这里只记副作用存在。下一课把 cache 容量本身按核切开。</p><p>后课默认：预取必须带反馈；默认攻击性不是最优。多核共享 LLC 时，还要按核或按类别切容量。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预取看覆盖、准确、污染、带宽四项，用反馈调 \\(k\\)。</li><li>错预取占用 MSHR 与一致性状态。</li><li>共享 cache 如何按核切开，是下一课分区。</li><li>出处：Srinath et al., <em>MICRO</em>, 2007；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const k=o(h,[["render",m]]);export{S as __pageData,k as default};
